            { "brief.scan", new[] { "Three beacons in the area have gone silent. Fly to each one, hover above it until the scan completes, then come home.", "Три маяка в районе замолчали. Долети до каждого, зависни над ним до конца сканирования и возвращайся." } },
            { "brief.recon", new[] { "Identify the enemy camp from the air, then sink the patrol boats guarding the bay. Rockets lock on whatever the nose points at.", "Опознай вражеский лагерь с воздуха, затем потопи сторожевые катера в бухте. Ракеты захватывают то, на что смотрит нос дрона." } },
            { "brief.photo", new[] { "Several objects need to be photographed. Get close or use the zoom, frame each one and take the shot.", "Несколько объектов нужно сфотографировать. Подлети ближе или включи зум, наведи камеру и сделай снимок." } },
            { "brief.race", new[] { "Ten gates and a clock. Fly through every gate in order and get back to the pad.", "Десять ворот и таймер. Пройди все ворота по порядку и вернись на площадку." } },
            { "brief.delivery", new[] { "A forward post is out of ammunition. Carry the load through to its pad, set it down gently and fly home.", "У передового поста кончились боеприпасы. Доставь груз на его площадку, посади мягко и возвращайся." } },
            { "brief.search", new[] { "An unknown transmitter is on the air. There is no marker: follow the scanner reading to its source, then scan it.", "В эфире неизвестный передатчик. Маркера нет: найди источник по показаниям сканера и просканируй его." } },
            { "brief.stealth", new[] { "Radars cover the way to the relay mast. They only see what flies above the red rings. Slip under them.", "Путь к мачте ретранслятора закрыт радарами. Они видят только то, что летит выше красных колец. Проскользни под ними." } },
            { "brief.tail", new[] { "A truck is on the move. Stay close enough to track it and far enough that the driver does not notice you.", "Грузовик в движении. Держись достаточно близко, чтобы вести его, и достаточно далеко, чтобы тебя не заметили." } },
            { "brief.strike", new[] { "One target, limited munitions. Climb to release height, let the red ring settle on the target, and release.", "Одна цель, боеприпасов в обрез. Набери высоту сброса, дождись, пока красное кольцо ляжет на цель, и сбрасывай." } },
            { "brief.escort", new[] { "A convoy is setting out and ambushes wait on its road. Find and mark every one before the trucks reach it.", "Колонна выходит в путь, на дороге её ждут засады. Найди и отметь каждую до подхода грузовиков." } },
            { "brief.storm", new[] { "Bad weather and a battery that is already low. Pass both gates and get home before the charge runs out.", "Непогода и уже севшая батарея. Пройди оба шлюза и вернись, пока хватает заряда." } },
            { "brief.special", new[] { "The final blow. Slip under the radar to photograph the papers at its foot, then break their last position: the guns, the tank and the headquarters.", "Финальный удар. Проскользни под радаром и сфотографируй документы у его подножия, затем разбей их последнюю позицию: зенитки, танк и штаб." } },
            { "region.arvelia.name", new[] { "Arvelia", "Арвелия" } },
            { "region.arvelia.note", new[] { "A green island under occupation. Cobalt's columns hold the roads and its guns hold the sky. Take both back.", "Зелёный остров под оккупацией. Колонны «Кобальта» держат дороги, его зенитки - небо. Верни и то, и другое." } },
            { "region.kharad.name", new[] { "Kharad", "Харад" } },
            { "region.kharad.note", new[] { "A dry coast of dunes and red rock. Cobalt's armour and its fuel come through here: burn the supply line.", "Сухой берег дюн и красных скал. Здесь идут броня и топливо «Кобальта»: сожги линию снабжения." } },
            { "region.nordheim.name", new[] { "Nordheim", "Нордхейм" } },
            { "region.nordheim.note", new[] { "Snow, high ridges and thin air. Cobalt's command has dug in under the ridge. Finish it.", "Снег, высокие хребты и разреженный воздух. Командование «Кобальта» окопалось под хребтом. Добей его." } },
            { "template.special", new[] { "SPECIAL OPERATION", "СПЕЦОПЕРАЦИЯ" } },
            { "objective.strike_moving", new[] { "Above {0} m: lead the moving target with the red ring, press FIRE", "Выше {0} м: веди красное кольцо с упреждением, жми ОГОНЬ" } },
