            { "globe.soon", new[] { "More regions are coming", "Новые регионы в разработке" } },
            { "loading", new[] { "LOADING", "ЗАГРУЗКА" } },
            { "talk.arvelia.speaker", new[] { "HARBOUR MASTER", "НАЧАЛЬНИК ПОРТА" } },
            { "talk.arvelia.text", new[] { "I know which generator feeds their radars. I also know what my silence is worth.", "Я знаю, какой генератор питает их радары. И знаю, чего стоит моё молчание." } },
            { "talk.arvelia.pay", new[] { "Pay him 300 credits to cut the power", "Заплатить 300 кредитов, чтобы он отключил питание" } },
            { "talk.arvelia.pay.reply", new[] { "One radar goes dark at dusk. Do not be late.", "Один радар погаснет в сумерках. Не опаздывай." } },
            { "talk.arvelia.plain", new[] { "Thank him and do it your own way", "Поблагодарить и сделать по-своему" } },
            { "talk.arvelia.plain.reply", new[] { "Your funeral. The radars stay on.", "Дело твоё. Радары остаются включёнными." } },
            { "talk.arvelia.risk", new[] { "Fly tonight, in the storm, for a bigger fee", "Лететь сегодня, в шторм, за больший гонорар" } },
            { "talk.arvelia.risk.reply", new[] { "In this weather? Then the client pays half again.", "В такую погоду? Тогда заказчик платит в полтора раза больше." } },
            { "talk.kharad.speaker", new[] { "CARAVAN GUIDE", "ПРОВОДНИК КАРАВАНА" } },
            { "talk.kharad.text", new[] { "Cobalt's watchers trust me. For a price, one of them will be looking the other way.", "Наблюдатели «Кобальта» мне доверяют. За плату один из них отвернётся." } },
            { "talk.kharad.pay", new[] { "Pay 300 credits for a blind radar", "Заплатить 300 кредитов за слепой радар" } },
            { "talk.kharad.pay.reply", new[] { "Done. The northern dish will be down for repairs.", "Сделано. Северная тарелка встанет на ремонт." } },
            { "talk.kharad.plain", new[] { "Keep the money, keep the plan", "Оставить деньги и план как есть" } },
            { "talk.kharad.plain.reply", new[] { "As you wish. Both dishes are awake.", "Как знаешь. Обе тарелки не спят." } },
            { "talk.kharad.risk", new[] { "Go in during the sandstorm for a bigger fee", "Идти в песчаную бурю за больший гонорар" } },
            { "talk.kharad.risk.reply", new[] { "Nobody flies in that. Which is why it pays.", "В такое никто не летает. Поэтому и платят." } },
            { "talk.nordheim.speaker", new[] { "STATION CHIEF", "НАЧАЛЬНИК СТАНЦИИ" } },
            { "talk.nordheim.text", new[] { "The signal comes from under the ridge. I can ice one of their antennas, if the station gets its fuel.", "Сигнал идёт из-под хребта. Я могу обледенить одну их антенну, если станция получит топливо." } },
            { "talk.nordheim.pay", new[] { "Send 300 credits for fuel", "Перевести 300 кредитов на топливо" } },
            { "talk.nordheim.pay.reply", new[] { "Fuel is on its way. One antenna will not survive the night.", "Топливо в пути. Одна антенна эту ночь не переживёт." } },
            { "talk.nordheim.plain", new[] { "No deal. Fly it as planned", "Без сделки. Лететь по плану" } },
            { "talk.nordheim.plain.reply", new[] { "Understood. Expect both antennas.", "Понял. Жди обе антенны." } },
            { "talk.nordheim.risk", new[] { "Fly into the blizzard for a bigger fee", "Лететь в буран за больший гонорар" } },
            { "talk.nordheim.risk.reply", new[] { "Madness. The council will pay well for madness.", "Безумие. Совет хорошо платит за безумие." } },
