            { "mission.coast_watch.title", new[] { "Coast Watch", "Береговой дозор" } },
            { "mission.coast_watch.brief", new[] { "An enemy camp has appeared above the bay. Identify it from the air, then sink the patrol boats that guard the water.", "Над бухтой появился вражеский лагерь. Опознай его с воздуха, затем потопи катера, которые стерегут воду." } },
            { "mission.evidence.title", new[] { "Evidence", "Улики" } },
            { "mission.evidence.brief", new[] {
