            { "template.demolition", new[] { "DEMOLITION", "УНИЧТОЖЕНИЕ ОБЪЕКТА" } },
            { "template.defend", new[] { "DEFENCE", "ОБОРОНА" } },
            { "template.kamikaze", new[] { "STRIKE DRONES", "УДАРНЫЕ ДРОНЫ" } },
            { "template.eliminate", new[] { "ELIMINATION", "ЛИКВИДАЦИЯ" } },
            { "template.airfield", new[] { "AIRFIELD RAID", "НАЛЁТ НА АЭРОДРОМ" } },
            { "template.naval", new[] { "NAVAL STRIKE", "УДАР ПО ФЛОТУ" } },
            { "brief.assault", new[] { "An enemy supply point stands unguarded close to the pad. Point the nose at a target, wait for the green frame and fire. The fuel truck takes its neighbours with it.", "Рядом с площадкой стоит неохраняемый пункт снабжения противника. Наведи нос на цель, дождись зелёной рамки и стреляй. Бензовоз взрывается вместе с соседями." } },
            { "brief.convoy", new[] { "A column is running along the coast road. Destroy every vehicle before it reaches the far end. Land on the pad if you run dry: the crew rearms you in seconds.", "По прибрежной дороге идёт колонна. Уничтожь все машины, пока они не дошли до конца пути. Кончился боезапас - сядь на площадку, расчёт перезарядит за секунды." } },
            { "brief.hunt", new[] { "Enemy armour has dug in among the ruins. Tanks shoot back at anything that hovers near them: strike from a distance and keep moving.", "Вражеская броня окопалась среди руин. Танки бьют по всему, что висит рядом: атакуй издалека и не стой на месте." } },
            { "brief.sead", new[] { "Guns and a radar close this sky. Take the guns out first, from as far as your rockets reach. A missile battery only sees what flies high: stay low near it.", "Небо здесь закрыто зенитками и радаром. Сначала выбей зенитки с предельной дальности ракет. Ракетная батарея видит только высоко летящих: рядом с ней держись низко." } },
            { "brief.demolition", new[] { "The headquarters is concrete: rockets barely scratch it. Silence the guards, then climb over the building and drop bombs where the red ring lies.", "Штаб из бетона: ракеты его едва царапают. Заставь охрану замолчать, затем поднимись над зданием и сбрось бомбы туда, где лежит красное кольцо." } },
            { "brief.defend", new[] { "Raiders are driving for our outpost beside the pad. Meet them on the road and stop every one. If the outpost falls, the mission is lost.", "К нашему посту у площадки идут рейдеры. Встреть их на дороге и останови всех. Если пост падёт, задание провалено." } },
            { "brief.kamikaze", new[] { "No rockets this time. Each strike drone is its own warhead: fly it straight into a target. There is one drone more than there are targets, so make each one count.", "В этот раз без ракет. Каждый ударный дрон сам себе боеголовка: веди его прямо в цель. Дронов на один больше, чем целей, так что не трать их зря." } },
            { "brief.eliminate", new[] { "The enemy commander is on the road with an escort. Only his car matters. Destroy it before the column reaches safety.", "Вражеский командир едет по дороге с охраной. Важна только его машина. Уничтожь её, пока колонна не ушла в безопасное место." } },
            { "brief.airfield", new[] { "Helicopters are parked on a field strip, with a fuel truck among them and a gun on watch. Burn them on the ground before they fly.", "На полевом аэродроме стоят вертолёты, между ними бензовоз, рядом дежурит зенитка. Сожги их на земле, пока не взлетели." } },
            { "brief.naval", new[] { "A warship and its boats are shelling the coast. The ship is armoured: bombs from above are what sinks it. Expect fire all the way in.", "Корабль с катерами обстреливает берег. Корабль бронирован: топят его бомбы сверху. Огонь будет всю дорогу." } },
