            { "msg.oneway_refused", new[] { "Kamikaze drones fly strike missions only. Pick another aircraft in the hangar.", "Дроны-камикадзе летают только на уничтожение. Выберите другой аппарат в ангаре." } },
            { "drone.wasp.name", new[] { "Wasp", "Wasp" } },
            { "drone.wasp.role", new[] { "KAMIKAZE DRONE", "ДРОН-КАМИКАДЗЕ" } },
            { "drone.wasp.note", new[] { "No weapons: it is the weapon. Six airframes per sortie, each flown straight into its target. Strike missions only.", "Оружия нет — он сам оружие. Шесть аппаратов на вылет, каждый ведёте прямо в цель. Только задания на уничтожение." } },
