            { "radio.callsign", new[] { "NEST", "ГНЕЗДО" } },
            { "radio.cleared", new[] { "You are cleared hot. Good hunting.", "Работу разрешаю. Удачной охоты." } },
            { "radio.weapons_free", new[] { "Target acquired. Weapons free.", "Цель в захвате. Огонь по готовности." } },
            { "radio.target_down", new[] { "Good effect on target. Come home.", "Цель поражена. Возвращайся на базу." } },
            { "radio.hull", new[] { "You are taking hits! Break off and get low.", "По тебе попадают! Выходи из-под огня, прижмись к земле." } },
            { "region.tessara.name", new[] { "Tessara", "Тессара" } },
            { "region.tessara.note", new[] { "Green islands in warm shallow water. Cobalt moves its cargo between them by boat: cut the sea lanes.", "Зелёные острова на тёплом мелководье. «Кобальт» возит грузы между ними на катерах — перережь морские пути." } },
            { "region.vulkar.name", new[] { "Vulkar", "Вулкар" } },
            { "region.vulkar.note", new[] { "Black sand and ash under a live volcano. Cobalt forges its armour here. Put the furnaces out.", "Чёрный песок и пепел под действующим вулканом. Здесь «Кобальт» куёт свою броню. Погаси печи." } },
            { "region.redrock.name", new[] { "Redrock", "Редрок" } },
            { "region.redrock.note", new[] { "Red tablelands cut by cliffs. The last of Cobalt's columns hide between the mesas. Leave them nowhere to go.", "Красные столовые горы, изрезанные обрывами. Последние колонны «Кобальта» прячутся между ними. Не оставь им выхода." } },
            { "talk.tessara.speaker", new[] { "HARBOUR PILOT", "ЛОЦМАН" } },
            { "talk.tessara.text", new[] { "I know which reef their radar barge sits on. For a price, it will drag its anchor tonight.", "Я знаю, на каком рифе стоит их баржа с радаром. За плату она сегодня ночью сорвётся с якоря." } },
            { "talk.tessara.pay", new[] { "Pay 300 credits for a drifting radar", "Заплатить 300 кредитов за дрейфующий радар" } },
            { "talk.tessara.pay.reply", new[] { "Done. By morning that barge will be somebody else's problem.", "Сделано. К утру эта баржа станет чужой заботой." } },
            { "talk.tessara.plain", new[] { "Keep the money, fly it as it is", "Оставить деньги, лететь как есть" } },
            { "talk.tessara.plain.reply", new[] { "Your choice. Both radars are watching the water.", "Дело твоё. Оба радара смотрят на воду." } },
            { "talk.tessara.risk", new[] { "Go in under the storm for a bigger fee", "Идти в шторм за больший гонорар" } },
            { "talk.tessara.risk.reply", new[] { "The boats stay in port in weather like that. You will not have that luxury.", "В такую погоду катера стоят в порту. Тебе такая роскошь не светит." } },
            { "talk.vulkar.speaker", new[] { "FOUNDRY ENGINEER", "ИНЖЕНЕР ЛИТЕЙНОЙ" } },
            { "talk.vulkar.text", new[] { "The ash eats their dishes. I service them. One can stay broken a day longer, if I am paid to be slow.", "Пепел разъедает их тарелки. Я их чиню. Одна может простоять сломанной лишний день — если мне заплатят за медлительность." } },
            { "talk.vulkar.pay", new[] { "Pay 300 credits for a slow repair", "Заплатить 300 кредитов за медленный ремонт" } },
            { "talk.vulkar.pay.reply", new[] { "Then I have lost my tools. A terrible thing. The east dish stays dark.", "Значит, я потерял инструменты. Ужасное дело. Восточная тарелка останется тёмной." } },
            { "talk.vulkar.plain", new[] { "No deal. Fly it as planned", "Без сделки. Лететь по плану" } },
            { "talk.vulkar.plain.reply", new[] { "As you like. Both dishes will be turning.", "Как хочешь. Обе тарелки будут вращаться." } },
            { "talk.vulkar.risk", new[] { "Fly through the ash storm for a bigger fee", "Лететь в пепельную бурю за больший гонорар" } },
            { "talk.vulkar.risk.reply", new[] { "The mountain is in a mood. So is whoever pays for this.", "Гора не в духе. Как и тот, кто за это платит." } },
            { "talk.redrock.speaker", new[] { "CANYON SMUGGLER", "КОНТРАБАНДИСТ" } },
            { "talk.redrock.text", new[] { "Their lookout on the north mesa buys his water from me. Thirsty men do not watch the sky.", "Их наблюдатель на северной горе покупает воду у меня. Кто хочет пить, на небо не смотрит." } },
            { "talk.redrock.pay", new[] { "Pay 300 credits for a dry lookout", "Заплатить 300 кредитов за наблюдателя без воды" } },
            { "talk.redrock.pay.reply", new[] { "My mule goes lame tomorrow. The north post will have other worries.", "Мой мул завтра захромает. Северному посту будет не до неба." } },
            { "talk.redrock.plain", new[] { "Keep the money, keep the plan", "Оставить деньги и план как есть" } },
            { "talk.redrock.plain.reply", new[] { "Then both posts drink well and see far.", "Тогда оба поста напьются и будут видеть далеко." } },
            { "talk.redrock.risk", new[] { "Go in during the dust storm for a bigger fee", "Идти в пыльную бурю за больший гонорар" } },
            { "talk.redrock.risk.reply", new[] { "The canyon will be a wall of sand. Do not ask me to come looking.", "Каньон станет стеной песка. Искать тебя не проси." } },
