            { "base.hangar.name", new[] { "Reserve hangar", "Резервный ангар" } },
            { "base.hangar.note", new[] { "Spare aircraft that take over when yours is shot down: one at level 2, two at level 4.", "Запасные аппараты, которые заменят сбитый: один на 2-м уровне, два на 4-м." } },
            { "base.workshop.name", new[] { "Workshop", "Мастерская" } },
            { "base.workshop.note", new[] { "Every aircraft takes 4% less damage per level.", "Каждый аппарат получает на 4% меньше урона за уровень." } },
            { "base.tower.name", new[] { "Control tower", "Вышка связи" } },
            { "base.tower.note", new[] { "Radio range grows by 6% per level.", "Дальность связи растёт на 6% за уровень." } },
            { "base.depot.name", new[] { "Ammunition depot", "Склад боеприпасов" } },
            { "base.depot.note", new[] { "One more rocket per level, one more bomb every second level.", "Плюс одна ракета за уровень, плюс одна бомба за два уровня." } },
            { "base.defences.name", new[] { "Defences", "Оборона" } },
            { "base.defences.note", new[] { "Gun turrets that fight beside the outpost in Survival, and fewer sectors lost to counter-attacks.", "Турели рядом с постом в «Выживании» и меньше секторов, потерянных в контратаках." } },
            { "base.treasury.name", new[] { "Supply office", "Служба снабжения" } },
            { "base.treasury.note", new[] { "Held sectors pay 20% more per level.", "Удержанные сектора приносят на 20% больше за уровень." } },
            { "armoury.warheads.name", new[] { "Warheads", "Боевые части" } },
            { "armoury.warheads.note", new[] { "Every weapon does 6% more damage per level.", "Всё оружие наносит на 6% больше урона за уровень." } },
            { "armoury.seekers.name", new[] { "Seekers", "Головки наведения" } },
            { "armoury.seekers.note", new[] { "Targets are locked from 5% farther per level.", "Захват цели на 5% дальше за уровень." } },
            { "armoury.cannon.name", new[] { "Cannon", "Пушка" } },
            { "armoury.cannon.note", new[] { "Cannons hit 8% harder and carry 10% more rounds per level.", "Пушки бьют на 8% сильнее и несут на 10% больше снарядов за уровень." } },
            { "armoury.countermeasures.name", new[] { "Countermeasures", "Средства защиты" } },
            { "armoury.countermeasures.note", new[] { "One more charge of jammer, flares or guided missiles every second level.", "Плюс один заряд помех, ловушек или управляемых ракет за два уровня." } },
            { "op.strike.name", new[] { "Strike", "Удар по позиции" } },
            { "op.strike.brief", new[] { "An enemy position with its guards. Take out the marked targets; the guns around them are your problem, not your objective.", "Позиция противника с охраной. Уничтожь отмеченные цели; стволы вокруг — твоя проблема, а не задача." } },
            { "op.convoy.name", new[] { "Convoy", "Колонна" } },
            { "op.convoy.brief", new[] { "A column is on the road. If any vehicle reaches the end of it alive, the operation has failed. After the first blast they will run.", "По дороге идёт колонна. Если хоть одна машина дойдёт до конца — операция провалена. После первого взрыва они рванут." } },
            { "op.defend.name", new[] { "Defence", "Оборона поста" } },
            { "op.defend.brief", new[] { "Raiders are driving at our outpost by the pad. Stop them before they shoot it to pieces.", "К нашему посту у площадки едут рейдеры. Останови их, пока они его не расстреляли." } },
            { "op.airpatrol.name", new[] { "Air patrol", "Воздушный патруль" } },
            { "op.airpatrol.brief", new[] { "Enemy drones are up and looking for you. Bring them down, then put out the radar that guides them.", "Вражеские дроны в воздухе и ищут тебя. Сбей их, затем уничтожь радар, который их наводит." } },
            { "op.train.name", new[] { "Armoured train", "Бронепоезд" } },
            { "op.train.brief", new[] { "An armoured train is crossing the island: a locomotive, ammunition wagons and gun wagons. Nothing of it may reach the end of the line.", "Через остров идёт бронепоезд: локомотив, вагоны с боеприпасами и зенитные платформы. До конца пути не должно дойти ничего." } },
            { "op.launcher.name", new[] { "Launcher", "Пусковая установка" } },
            { "op.launcher.brief", new[] { "A missile launcher is driving to its firing point with an escort. Destroy it before it gets there.", "Ракетная установка с охраной едет на огневую позицию. Уничтожь её, пока не доехала." } },
            { "op.bridge.name", new[] { "Bridge", "Мост" } },
            { "op.bridge.brief", new[] { "Their supplies cross one bridge. Bombs bring concrete down; rockets barely scratch it.", "Их снабжение идёт через один мост. Бетон берут бомбы; ракеты его едва царапают." } },
            { "op.rescue.name", new[] { "Rescue", "Спасение пилота" } },
            { "op.rescue.brief", new[] { "One of ours is down and a search party is driving to him. Stop them, land beside him, and bring him home.", "Наш пилот сбит, к нему едет поисковая группа. Останови её, сядь рядом с пилотом и привези его домой." } },
            { "op.nighthunt.name", new[] { "Night hunt", "Ночная охота" } },
            { "op.nighthunt.brief", new[] { "Armour is parked up for the night. Switch to the gun camera: through the thermal sight warm engines stand out of the dark.", "Броня встала на ночёвку. Включи прицельную камеру: в тепловизоре тёплые моторы видны в темноте." } },
            { "op.platform.name", new[] { "Platform", "Нефтяная платформа" } },
            { "op.platform.brief", new[] { "An oil platform out at sea, with guard boats. It takes bombs, and it takes its neighbours with it.", "Нефтяная платформа в море, с катерами охраны. Её берут бомбы, а взрываясь, она забирает соседей." } },
            { "op.flagship.name", new[] { "Flagship", "Флагман" } },
            { "op.flagship.brief", new[] { "A command ship. While its turrets stand the hull shrugs off almost everything: knock the turrets out first.", "Штабной корабль. Пока стоят башни, корпус почти ничем не взять: сначала выбей башни." } },
            { "op.offensive.name", new[] { "Offensive", "Наступление" } },
            { "op.offensive.brief", new[] { "Our tanks are advancing on their line. Everything on that line will shoot at them. Clear it before our armour is lost.", "Наши танки идут на их рубеж. Всё, что на нём стоит, будет по ним стрелять. Расчисти рубеж, пока мы не потеряли броню." } },
            { "op.survival.title", new[] { "Survival", "Выживание" } },
            { "op.survival.brief", new[] { "Wave after wave drives at the outpost by the pad. Land on the pad between waves to rearm. It ends when the outpost falls or you do.", "Волна за волной идёт на пост у площадки. Между волнами садись на площадку перезарядиться. Конец — когда падёт пост или ты." } },
            { "op.raid.title", new[] { "Raid", "Рейд" } },
            { "op.armour.title", new[] { "ARMOURED RAID", "БРОНЕРЕЙД" } },
            { "op.armour.brief", new[] { "No aircraft this time. Drive out from the base, find the enemy position by road and break it with the gun. Hills hide you and them alike: fire from where you can see. Come back to the base when it is done.", "В этот раз без авиации. Выезжай с базы, доберись до позиции противника по земле и разбей её из пушки. Холмы прячут и тебя, и их: стреляй оттуда, откуда видно. Закончишь — возвращайся на базу." } },
            { "op.sniper.title", new[] { "OVERWATCH", "СНАЙПЕР" } },
            { "op.sniper.brief", new[] { "The aircraft hangs over the ridge, out of earshot. You have a rifle and a handful of rounds. A round takes a moment to arrive and sinks on the way: hold a little high, and ahead of a man who is walking. Every round counts.", "Аппарат висит над гребнем, откуда его не слышно. У тебя винтовка и горсть патронов. Пуля летит долю секунды и снижается: бери чуть выше, а по идущему — с упреждением. Каждый патрон на счету." } },
            { "objective.op.armour.go", new[] { "Move out", "Выдвигайся" } },
            { "objective.op.armour.back", new[] { "Drive back to the pad", "Вернись на площадку" } },
            { "hint.drive", new[] { "Push this stick forward to drive", "Толкни этот стик вперёд, чтобы поехать" } },
            { "hint.drive.move", new[] { "DRIVE · STEER", "ХОД · РУЛЬ" } },
            { "hint.drive.turn", new[] { "TURN", "ПОВОРОТ" } },
            { "hint.aim", new[] { "AIM", "ПРИЦЕЛ" } },
            { "objective.op.armour", new[] { "Destroy the enemy position: {0} left", "Уничтожь позицию противника: осталось {0}" } },
            { "objective.op.sniper", new[] { "Take out every man on the square: {0} left", "Сними всех на площади: осталось {0}" } },
            { "hq.armour.note", new[] { "On the ground in the {0}", "По земле на машине «{0}»" } },
            { "hq.sniper.note", new[] { "{0} targets, {1} rounds", "Целей: {0}, патронов: {1}" } },
