            { "fail.OutOfAmmo", new[] { "Out of rounds", "Патроны кончились" } },
            { "chain.first", new[] { "FIRST BLOOD", "ПЕРВАЯ КРОВЬ" } },
            { "chain.2", new[] { "DOUBLE KILL", "ДВОЙНОЕ УНИЧТОЖЕНИЕ" } },
            { "chain.3", new[] { "TRIPLE KILL", "ТРОЙНОЕ УНИЧТОЖЕНИЕ" } },
