            { "chain.bonus", new[] { "+{0} credits", "+{0} кредитов" } },
            { "field.hit", new[] { "HIT", "ПОПАДАНИЕ" } },
            { "pickup.repair", new[] { "REPAIR +25%", "РЕМОНТ +25%" } },
            { "pickup.ammo", new[] { "AMMUNITION", "БОЕЗАПАС" } },
            { "pickup.credits", new[] { "CREDITS", "КРЕДИТЫ" } },
            { "prologue.title", new[] { "WEAPONS FREE", "ОГОНЬ РАЗРЕШЁН" } },
            { "prologue.sub", new[] { "This is what you will fly. Destroy the position.", "Вот на чём ты будешь летать. Уничтожь позицию." } },
            { "pickup.part", new[] { "BLUEPRINT PART", "ДЕТАЛЬ ЧЕРТЕЖА" } },
            { "result.blueprints", new[] { "Blueprint parts found: +{0}", "Найдено деталей чертежей: +{0}" } },
            { "result.loot", new[] { "Picked up on the field: +{0} ({1} crates)", "Подобрано на поле боя: +{0} (ящиков: {1})" } },
            { "result.chain", new[] { "Best chain: {0} in a row, +{1}", "Лучшая серия: {0} подряд, +{1}" } },
            { "result.clean", new[] { "Not a round wasted: +{0}", "Ни одного промаха: +{0}" } },
            { "scope.data", new[] { "RANGE {0} m\nWIND {1} m/s\nZOOM ×{2}", "ДАЛЬНОСТЬ {0} м\nВЕТЕР {1} м/с\nКРАТНОСТЬ ×{2}" } },
            { "scope.rounds", new[] { "ROUNDS {0}   ·   TARGETS {1}", "ПАТРОНЫ {0}   ·   ЦЕЛИ {1}" } },
            { "coach.title", new[] { "INSTRUCTOR  ·  {0}/{1}", "ИНСТРУКТОР  ·  {0}/{1}" } },
            { "coach.fly.0", new[] { "Push the lift stick up to take off, and climb above the trees.", "Потяни стик высоты вверх — взлетай и поднимись выше деревьев." } },
            { "coach.fly.1", new[] { "The other stick flies the drone: forward, back and sideways. Fly a little way forward.", "Второй стик ведёт дрон: вперёд, назад и в стороны. Пролети немного вперёд." } },
            { "coach.fly.2", new[] { "Left and right on the lift stick turn the nose. Turn around and look about.", "Влево и вправо на стике высоты — поворот носа. Развернись и осмотрись." } },
            { "coach.fly.3", new[] { "The orange marker shows where to go, the line at the top says what to do. To finish, come back to the pad: the LANDING button sets the drone down by itself.", "Оранжевая метка показывает, куда лететь, строка вверху — что делать. В конце вернись на площадку: кнопка «ПОСАДКА» посадит дрон сама." } },
            { "coach.fight.0", new[] { "The ring in the middle is your sight. Turn it onto an enemy: it goes green when the target is locked, and that works from far away.", "Кольцо в центре экрана — прицел. Наведи его на противника: оно станет зелёным, когда цель захвачена. Захват работает издалека." } },
            { "coach.fight.1", new[] { "Press ROCKETS. With a lock the rocket homes; without one it flies to where the sight is looking.", "Жми «РАКЕТЫ». С захватом ракета наводится сама, без захвата летит туда, куда смотрит прицел." } },
            { "coach.fight.2", new[] { "Bombs fall under the drone and hit harder: fly over the target and press BOMBS. Stay out of the red circles of the guns.", "Бомбы падают под дрон и бьют сильнее: пролети над целью и жми «БОМБЫ». В красные круги зениток не залетай." } },
            { "coach.fight.3", new[] { "Wrecks leave crates under a pillar of light: green repairs, orange rearms, gold pays. Fly through them.", "Из подбитой техники выпадают ящики под столбом света: зелёный — ремонт, оранжевый — боезапас, золотой — кредиты. Пролети сквозь них." } },
            { "coach.drive.0", new[] { "The move stick drives: forward, back, and left and right to steer. The other stick turns the hull too.", "Стик движения — газ и руль: вперёд, назад, влево и вправо. Второй стик тоже поворачивает корпус." } },
            { "coach.drive.1", new[] { "Follow the marker to the enemy. Water, cliffs and walls stop a vehicle; trees do not.", "Иди по метке к противнику. Вода, обрывы и стены машину останавливают, деревья — нет." } },
            { "coach.drive.2", new[] { "Turn the hull onto the target until the sight goes green, then fire. From behind a hill there is no lock: drive to where you can see.", "Доверни корпус на цель, пока прицел не станет зелёным, и стреляй. Из-за холма захвата нет: выезжай туда, откуда видно." } },
            { "coach.snipe.0", new[] { "Either stick moves the rifle. The ZOOM button changes the magnification: the closer the glass, the finer the aim.", "Любой стик двигает винтовку. Кнопка «ЗУМ» меняет кратность: чем ближе, тем точнее наводка." } },
            { "coach.snipe.1", new[] { "The round takes a moment and sinks: the ticks under the cross are for far targets. Lead a man who is walking.", "Пуля летит долю секунды и снижается: штрихи под перекрестьем — для дальних целей. По идущему бери упреждение." } },
            { "coach.snipe.2", new[] { "Press FIRE. You have fewer rounds than you would like.", "Жми «ОГОНЬ». Патронов меньше, чем хотелось бы." } },
            { "drone.bulldog.name", new[] { "Bulldog", "Bulldog" } },
            { "drone.bulldog.role", new[] { "ARMOURED CARRIER", "БРОНЕТРАНСПОРТЁР" } },
            { "drone.bulldog.note", new[] { "Everybody's first vehicle: a 30 mm gun, a machine gun and armour that shrugs off rifle fire. For armoured raids only.", "Первая машина каждого: 30-мм пушка, пулемёт и броня, которой не страшны автоматы. Только для бронерейдов." } },
            { "drone.lynx.name", new[] { "Lynx", "Lynx" } },
            { "drone.lynx.role", new[] { "FAST ATTACK CAR", "БЫСТРЫЙ БРОНЕАВТОМОБИЛЬ" } },
            { "drone.lynx.note", new[] { "Twice as fast as anything else on tracks or wheels, with a quick-firing gun. Thin skin: hit and move on.", "Вдвое быстрее всего, что ездит, и со скорострельной пушкой. Броня тонкая: ударил — уходи." } },
            { "drone.rhino.name", new[] { "Rhino", "Rhino" } },
            { "drone.rhino.role", new[] { "MAIN BATTLE TANK", "ОСНОВНОЙ БОЕВОЙ ТАНК" } },
            { "drone.rhino.note", new[] { "A real tank: a gun that kills armour in two rounds and a hull that takes what comes back.", "Настоящий танк: пушка, которая берёт броню с двух снарядов, и корпус, который держит ответный огонь." } },
            { "drone.mammoth.name", new[] { "Mammoth", "Mammoth" } },
            { "drone.mammoth.role", new[] { "HEAVY TANK", "ТЯЖЁЛЫЙ ТАНК" } },
            { "drone.mammoth.note", new[] { "Slow, and nothing on the island stops it. The heaviest gun there is and the longest reach.", "Медленный — и ничто на острове его не остановит. Самая тяжёлая пушка и самая большая дальность." } },
            { "drone.overwatch.name", new[] { "Overwatch", "Overwatch" } },
            { "drone.overwatch.role", new[] { "SNIPER PLATFORM", "СНАЙПЕРСКАЯ ПЛАТФОРМА" } },
            { "drone.overwatch.note", new[] { "Hangs still and carries a rifle.", "Висит неподвижно и несёт винтовку." } },
            { "hangar.vehicle", new[] { "Shells {0} × {1}   Machine gun {2} s\nLock {3} m   Armour ×{4}", "Снаряды {0} × {1}   Пулемёт {2} с\nЗахват {3} м   Броня ×{4}" } },
            { "hangar.ground", new[] { "GROUND VEHICLE  ·  ARMOURED RAIDS", "НАЗЕМНАЯ ТЕХНИКА  ·  БРОНЕРЕЙДЫ" } },
            { "hud.shells", new[] { "SHELLS {0}", "СНАРЯДЫ {0}" } },
            { "settings.lessons", new[] { "REPEAT TRAINING", "ПОВТОРИТЬ ОБУЧЕНИЕ" } },
            { "msg.lessons", new[] { "Training will start again on the next sortie", "Обучение начнётся заново в следующем вылете" } },
            { "splash.tag", new[] { "GLOBAL OPERATIONS", "GLOBAL OPERATIONS" } },
            { "splash.sub", new[] { "UNMANNED STRIKE COMMAND", "КОМАНДОВАНИЕ БЕСПИЛОТНЫХ УДАРНЫХ СИЛ" } },
            { "splash.boot.0", new[] { "LINK ESTABLISHED", "СВЯЗЬ УСТАНОВЛЕНА" } },
            { "splash.boot.1", new[] { "SATELLITE FEED ONLINE", "СПУТНИКОВЫЙ КАНАЛ АКТИВЕН" } },
            { "splash.boot.2", new[] { "FLEET READY", "ТЕХНИКА ГОТОВА" } },
            { "splash.tap", new[] { "TAP TO CONTINUE", "КОСНИСЬ, ЧТОБЫ ПРОДОЛЖИТЬ" } },
            { "op.raid.brief", new[] { "Supply drops lie deep in their territory. Hold over each one to mark it, then get out. Every drop you mark wakes more of the hunt.", "В глубине их территории лежат грузы. Зависни над каждым, чтобы отметить, и уходи. Каждый отмеченный груз поднимает новых охотников." } },
            { "op.range.title", new[] { "Firing range", "Полигон" } },
            { "op.range.brief", new[] { "One of everything to shoot at, racks that never empty, nothing that shoots back. Try any aircraft before you buy it.", "По одной цели каждого вида, боезапас не кончается, никто не стреляет в ответ. Попробуй любой аппарат до покупки." } },
